def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    threat_scores = []

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = None
            if prev:
                bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                score = float(bid)
                if opp.get('no_water_days', 0) >= 1:
                    score += 8.0
                if opp.get('hp', 0) <= 3:
                    score += 10.0
                if opp.get('budget', 0) < 40:
                    score -= 6.0
                threat_scores.append(score)

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.25))

    # Supply pressure: lower supply means tighter competition.
    pressure = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if pressure < 0:
        pressure = 0.0
    if pressure > 1:
        pressure = 1.0

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_threat = max(threat_scores) if threat_scores else highest_prev

    # Baseline conservation.
    base = DAILY_SALARY * (0.34 + 0.30 * pressure)

    # React to market from yesterday.
    if highest_prev > 0:
        if pressure >= 0.7:
            target = max(base, highest_threat + 2.5)
        elif pressure >= 0.4:
            target = max(base, highest_prev * 0.88 + 2.0)
        else:
            target = max(base, highest_prev * 0.68)
    else:
        target = base

    # Survival escalation.
    if hp <= 2 or no_water >= 2:
        target = max(target, DAILY_SALARY * 0.96, highest_prev + 3.0)
    elif hp <= 4 or no_water >= 1:
        target = max(target, DAILY_SALARY * (0.72 + 0.10 * pressure))

    # Endgame: avoid dying with money.
    if day >= 8:
        target = max(target, DAILY_SALARY * (0.58 + 0.18 * pressure))
        if hp <= 4:
            target = max(target, DAILY_SALARY * 0.9)

    # Budget discipline.
    reserve_days = max(0, 10 - day)
    soft_cap = budget
    if reserve_days > 0 and hp > 3:
        soft_cap = min(soft_cap, budget * 0.42 + DAILY_SALARY * 0.35)
    elif hp > 2:
        soft_cap = min(soft_cap, budget * 0.58 + DAILY_SALARY * 0.45)

    bid = min(target, soft_cap, budget)

    # Keep bids sensible and positive.
    floor_bid = 8.0 if pressure < 0.3 else 15.0
    if hp <= 3 or no_water >= 1:
        floor_bid = max(floor_bid, 28.0)
    bid = max(floor_bid, bid)
    bid = min(bid, budget)

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 150
    WATER_REQ = 13

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.55

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3:
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            else:
                return min(my_status['budget'], DAILY_SALARY * 0.95)

        else:
            return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 2.0))

    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.9)

    return min(my_status['budget'], base_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids of alive opponents for immediate reaction.
    yesterday_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', None)
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    # If we have no usable yesterday bids, use a conservative baseline.
    if not yesterday_bids:
        base = DAILY_SALARY * 0.6
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.85
        return max(0.0, min(budget, base))

    highest_prev_bid = max(yesterday_bids)

    # Supply pressure: with higher supply we can bid slightly less; with lower supply bid more.
    # Our need is 7; supply is 15-25 so we usually can secure water if close to key bidders.
    supply_factor = (supply - 15.0) / (25.0 - 15.0)  # 0..1
    # When supply is low, be more aggressive.
    aggression = 0.85 - 0.2 * supply_factor  # ~0.85 when low, ~0.65 when high

    # If yesterday's top bids were high, we must match/beat that pressure to stay on water.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if hp > 3 and no_water_days <= 1:
            target = DAILY_SALARY * 0.78 * aggression
        else:
            target = DAILY_SALARY * 0.95 * aggression
    else:
        # Otherwise, bid around just above the observed highest to avoid losing the water allocation.
        # Add a small premium.
        target = min(DAILY_SALARY * 0.75, highest_prev_bid + 6.0)
        target = target * aggression
        if hp <= 2 or no_water_days >= 2:
            target = max(target, DAILY_SALARY * 0.85 * aggression)

    # Ensure we don't overspend: keep some buffer for future days.
    # If budget is low relative to target, spend what we can.
    spend_cap = budget
    if budget > DAILY_SALARY * 1.2:
        spend_cap = min(budget, DAILY_SALARY * 1.05)

    bid = max(0.0, min(spend_cap, target))
    return bid
